@Repository
public class ApiKeys {
  private static final Pattern FORMAT = Pattern.compile("rb_live_([0-9a-f]{8})_[A-Za-z0-9_-]{43}");
  private static final SecureRandom RANDOM = new SecureRandom();

  public record Key(long id, long buildingId, List<String> scopes) {}
  public record Created(long id, String key, String prefix) {}
  record Row(long id, long buildingId, String[] scopes, String keyHash) {}

  private final JdbcClient jdbc;

  public ApiKeys(JdbcClient jdbc) {
    this.jdbc = jdbc;
  }

  public Created create(String name, long buildingId, List<String> scopes) {
    byte[] id = new byte[4];
    byte[] secret = new byte[32];
    RANDOM.nextBytes(id);
    RANDOM.nextBytes(secret);
    String prefix = HexFormat.of().formatHex(id);
    String key = "rb_live_" + prefix + "_" + Base64.getUrlEncoder().withoutPadding().encodeToString(secret);
    long keyId = jdbc.sql("""
        INSERT INTO api_keys (prefix, key_hash, name, building_id, scopes)
        VALUES (?, ?, ?, ?, ?) RETURNING id""")
        .params(prefix, RefreshTokens.sha256(key), name, buildingId, scopes.toArray(String[]::new))
        .query(Long.class).single();
    return new Created(keyId, key, prefix);
  }

  public Optional<Key> check(String presented) {
    var match = FORMAT.matcher(presented);
    if (!match.matches()) return Optional.empty();
    return jdbc.sql("""
        SELECT id, building_id, scopes, key_hash FROM api_keys
        WHERE prefix = ? AND revoked_at IS NULL""")
        .param(match.group(1))
        .query((rs, n) -> new Row(rs.getLong(1), rs.getLong(2),
            (String[]) rs.getArray(3).getArray(), rs.getString(4)))
        .optional()
        .filter(row -> MessageDigest.isEqual(
            RefreshTokens.sha256(presented).getBytes(), row.keyHash().getBytes()))
        .map(row -> {
          jdbc.sql("""
              UPDATE api_keys SET last_used_at = now()
              WHERE id = ? AND (last_used_at IS NULL OR last_used_at < now() - interval '1 minute')""")
              .param(row.id()).update();
          return new Key(row.id(), row.buildingId(), List.of(row.scopes()));
        });
  }
}

