@Component
public class SsoLogin implements AuthenticationSuccessHandler {
  private final IdentityLinker identities;
  private final UserRepository users;

  public SsoLogin(IdentityLinker identities, UserRepository users) {
    this.identities = identities;
    this.users = users;
  }

  public static void configure(HttpSecurity http, SsoLogin sso) throws Exception {
    http.oauth2Login(login -> login
        .authorizationEndpoint(a -> a.baseUri("/v1/auth/sso/start"))
        .redirectionEndpoint(r -> r.baseUri("/v1/auth/sso/callback/*"))
        .successHandler(sso));
  }

  @Override
  public void onAuthenticationSuccess(HttpServletRequest request, HttpServletResponse response,
                    Authentication authentication) throws IOException {
    OidcUser oidc = (OidcUser) authentication.getPrincipal();
    long userId = identities.link(oidc.getIssuer().toString(), oidc.getSubject(),
        oidc.getEmail(), Boolean.TRUE.equals(oidc.getEmailVerified()));
    UserRow user = users.findById(userId).orElseThrow();

    var auth = new RoombookAuthentication(
        Roles.user("session", user.id(), user.role(), user.buildingId(), null));
    new ChangeSessionIdAuthenticationStrategy().onAuthentication(auth, request, response);
    var context = SecurityContextHolder.createEmptyContext();
    context.setAuthentication(auth);
    SecurityContextHolder.setContext(context);
    new HttpSessionSecurityContextRepository().saveContext(context, request, response);
    response.sendRedirect("https://app.roombook.example/");
  }
}

@Repository
public class IdentityLinker {
  private final JdbcClient jdbc;

  public IdentityLinker(JdbcClient jdbc) {
    this.jdbc = jdbc;
  }

  @Transactional
  public long link(String issuer, String subject, String email, boolean emailVerified) {
    Optional<Long> linked = jdbc.sql("SELECT user_id FROM oidc_identities WHERE issuer = ? AND subject = ?")
        .params(issuer, subject).query(Long.class).optional();
    if (linked.isPresent()) return linked.get();

    if (!emailVerified || email == null) {
      throw new AccessDeniedException("Your university account has no verified email.");
    }
    long userId = jdbc.sql("SELECT id FROM users WHERE lower(email) = lower(?) AND role IN ('staff', 'admin')")
        .param(email).query(Long.class).optional()
        .orElseThrow(() -> new AccessDeniedException("Ask an admin to add you as staff first."));
    jdbc.sql("INSERT INTO oidc_identities (issuer, subject, user_id) VALUES (?, ?, ?)")
        .params(issuer, subject, userId).update();
    return userId;
  }
}

