// auth/RoombookAuthentication.java
public class RoombookAuthentication extends AbstractAuthenticationToken {
  private final RoombookPrincipal principal;

  public RoombookAuthentication(RoombookPrincipal principal) {
    super(authoritiesOf(principal));
    this.principal = principal;
    setAuthenticated(true);
  }

  private static List<GrantedAuthority> authoritiesOf(RoombookPrincipal p) {
    List<GrantedAuthority> authorities = new ArrayList<>();
    if (p.role() != null) authorities.add(new SimpleGrantedAuthority("ROLE_" + p.role().toUpperCase()));
    p.scopes().forEach(s -> authorities.add(new SimpleGrantedAuthority("SCOPE_" + s)));
    return authorities;
  }
  // getPrincipal, getName, getCredentials
}

  private static void rules(AuthorizeHttpRequestsConfigurer<HttpSecurity>.AuthorizationManagerRequestMatcherRegistry r) {
    r.requestMatchers("/error").permitAll()
        .requestMatchers(HttpMethod.POST, "/v1/auth/**").permitAll()
        .requestMatchers(HttpMethod.POST, "/v1/rooms").hasAnyRole("STAFF", "ADMIN")
        .requestMatchers(HttpMethod.GET, "/v1/rooms/*/schedule").hasAuthority("SCOPE_schedule:read")
        .requestMatchers("/v1/api-keys/**").hasAuthority("SCOPE_api-keys:write")
        .requestMatchers(HttpMethod.GET, "/v1/bookings/**").hasAuthority("SCOPE_bookings:read")
        .anyRequest().authenticated();
  }

